CREATE TABLE countries (code2 TEXT NOT NULL PRIMARY KEY, code3 TEXT NOT NULL, name TEXT NOT NULL);

CREATE TABLE IP_Ranges (min NUMERIC NOT NULL, max NUMERIC NOT NULL, code2 NOT NULL);

CREATE TABLE pages_stat (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, http_referer TEXT NOT NULL UNIQUE, visits_count INTEGER NOT NULL);

CREATE TABLE no_log_ip (ip TEXT PRIMARY KEY NOT NULL);

CREATE TABLE visitors (v_ip TEXT NOT NULL PRIMARY KEY, v_first_datetime DATETIME, v_last_datetime DATETIME NOT NULL, v_sessions INTEGER NOT NULL DEFAULT (0), v_pages INTEGER NOT NULL, c_code2 TEXT);

CREATE TABLE REQUEST_LOG (ID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, EVENT_TIME DATETIME, USER_IP TEXT, REQUEST_URI TEXT, HTTP_USER_AGENT TEXT, HTTP_ACCEPT_LANGUAGE TEXT, HTTP_REFERER TEXT, c_code2 TEXT);

